	values.Set("postedTo", query.PostedTo)
	if apiKey != "" {
		// SAM.gov Opportunities API v2 documents api_key as a query parameter;
		// no Authorization header alternative is documented for this endpoint.
		values.Set("api_key", apiKey)
	}
	if query.Query != "" {
		values.Set("title", query.Query)
	}
	if query.NAICS != "" {
		values.Set("ncode", query.NAICS)
	}
	if query.Organization != "" {
		values.Set("organizationName", query.Organization)
	}
	if query.State != "" {
		values.Set("state", query.State)
	}
	if query.Type != "" {
		values.Set("ptype", query.Type)
	}
	return samOpportunitiesURL + "?" + values.Encode()
